      RustLib.instance.api.crateApiSessionTerminalSessionWatch(that: this);

  /// `lines` notches, positive up.
  void wheel({
    required int lines,
    required double x,
    required double y,
    required int mods,
  }) => RustLib.instance.api.crateApiSessionTerminalSessionWheel(
    that: this,
    lines: lines,
    x: x,
    y: y,
    mods: mods,
  );
}
